**模板二**：預處理 $x$ 的最小質因子 $\text{LPF}(x)$，從而做到 $\mathcal{O}(\log x)$ 分解 $x$，求出 $x$ 的質因子及其出現次數。

```py [sol-Python3]
MX = 1_000_001  # **根據題目資料範圍修改**
lpf = [0] * MX
for i in range(2, MX):
    if lpf[i] == 0:  # i 是質數
        for j in range(i, MX, i):
            if lpf[j] == 0:  # 首次訪問 j
                lpf[j] = i

# 質因數分解
# 例如 prime_factorization(45) = [(3, 2), (5, 1)]，表示 45 = 3**2 * 5**1
# 時間複雜度 O(log x)
def prime_factorization(x: int) -> list[tuple[int, int]]:
    res = []
    while x > 1:
        p = lpf[x]
        e = 1
        x //= p
        while x % p == 0:
            e += 1
            x //= p
        res.append((p, e))
    return res
```

```java [sol-Java]
class Solution {
    private static final int MX = 1_000_001; // **根據題目資料範圍修改**
    private static final int[] lpf = new int[MX];
    private static boolean initialized = false;

    // 這樣寫比 static block 快
    public Solution() {
        if (initialized) {
            return;
        }
        initialized = true;

        for (int i = 2; i < MX; i++) {
            if (lpf[i] == 0) { // i 是質數
                for (int j = i; j < MX; j += i) {
                    if (lpf[j] == 0) { // 首次訪問 j
                        lpf[j] = i;
                    }
                }
            }
        }
    }

    // 質因數分解
    // 例如 primeFactorization(45) = [[3, 2], [5, 1]]，表示 45 = 3^2 * 5^1
    // 時間複雜度 O(log x)
    private List<int[]> primeFactorization(int x) {
        List<int[]> res = new ArrayList<>();
        while (x > 1) {
            int p = lpf[x];
            int e = 1;
            for (x /= p; x % p == 0; x /= p) {
                e++;
            }
            res.add(new int[]{p, e});
        }
        return res;
    }

