**模板一**：計算一個數的所有因子。

```py [sol-Python3]
# 返回正整數 n 的所有因子（未排序）
# 時間複雜度 O(√n)
def calc_divisors(n: int) -> list[int]:
    divisors = []
    for d in range(1, math.isqrt(n) + 1):
        if n % d == 0:
            divisors.append(d)
            if d * d < n:
                divisors.append(n // d)
    return divisors
```

```java [sol-Java]
class Solution {
    // 返回正整數 n 的所有因子（未排序）
    // 時間複雜度 O(√n)
    private List<Integer> divisors(int n) {
        List<Integer> divisors = new ArrayList<>();
        for (int d = 1; d * d <= n; d++) {
            if (n % d == 0) {
                divisors.add(d);
                if (d * d < n) {
                    divisors.add(n / d);
                }
            }
        }
        return divisors;
    }
}
```

